// Generated by `dokimos verification scaffold` from plan VP-B2-EVIDENCE. Each body fails until
// it is written; `dokimos verification coverage` reports DOKIMOS-UNIMPLEMENTED as a placeholder.
namespace Evidence.Tests

open System
open System.IO
open Xunit
open Evidence

module EVD003Tests =
    let private withTempDir (f: string -> unit) =
        let dir = Path.Combine(Path.GetTempPath(), "evd003-" + Guid.NewGuid().ToString("N"))
        Directory.CreateDirectory dir |> ignore
        try f dir
        finally (try Directory.Delete(dir, true) with _ -> ())

    let private makeRecord (id: string) (size: int) =
        let rng = Random(3003 + size)
        let bytes = Array.init size (fun _ -> byte (rng.Next 256))
        match Evidence.create id ("https://provider.example/evidence/" + id) "collector-a" bytes with
        | Ok r -> r
        | Error e -> failwithf "fixture record could not be created: %A" e

    let private saveOk (store: EvidenceStore) (record: EvidenceRecord) =
        match store.Save record with
        | Ok () -> ()
        | Error e -> failwithf "Save failed: %A" e

    /// EVD-003-O1: a saved record loads back equal to the saved record.
    [<Fact>]
    let ``EVD-003-O1`` () : unit =
        withTempDir (fun dir ->
            let store = EvidenceStore(dir)
            let records = [ makeRecord "ev-a" 0; makeRecord "ev-b" 17; makeRecord "ev-c" 65536 ]
            records |> List.iter (saveOk store)
            records
            |> List.iter (fun record ->
                match store.Load record.Id with
                | Ok loaded ->
                    Assert.True((loaded = record), sprintf "loaded record differs for %s" record.Id)
                    Assert.Equal(record.Id, loaded.Id)
                    Assert.Equal(record.Source, loaded.Source)
                    Assert.Equal(record.CollectedBy, loaded.CollectedBy)
                    Assert.Equal(record.Sha256, loaded.Sha256)
                    Assert.Equal<byte>(record.Content, loaded.Content)
                | Error e -> failwithf "Load %s failed: %A" record.Id e)
            // A fresh store over the same directory also reads it back.
            let reopened = EvidenceStore(dir)
            records
            |> List.iter (fun record ->
                match reopened.Load record.Id with
                | Ok loaded -> Assert.True((loaded = record))
                | Error e -> failwithf "reopened Load %s failed: %A" record.Id e))

    /// EVD-003-O2: if the stored content is altered after saving, `load` returns `Error(IntegrityFailure id)`, never `Ok`.
    [<Fact>]
    let ``EVD-003-O2`` () : unit =
        let alterations : (string * (byte[] -> byte[])) list =
            [ "flip-first", (fun b -> b |> Array.mapi (fun i x -> if i = 0 then x ^^^ 0xFFuy else x))
              "flip-middle", (fun b -> b |> Array.mapi (fun i x -> if i = b.Length / 2 then x ^^^ 0x01uy else x))
              "append", (fun b -> Array.append b [| 7uy |])
              "truncate", (fun b -> Array.sub b 0 (b.Length - 1)) ]

        alterations
        |> List.iter (fun (name, alter) ->
            withTempDir (fun dir ->
                let id = "ev-" + name
                let record = makeRecord id 1024
                let store = EvidenceStore(dir)
                saveOk store record
                let binPath = Path.Combine(dir, id + ".bin")
                Assert.True(File.Exists binPath, sprintf "expected content file %s" binPath)
                let original = File.ReadAllBytes binPath
                let altered = alter original
                Assert.False((altered = original))
                File.WriteAllBytes(binPath, altered)
                match store.Load id with
                | Error (IntegrityFailure failedId) -> Assert.Equal(id, failedId)
                | Error other -> failwithf "%s: expected IntegrityFailure, got %A" name other
                | Ok r -> failwithf "%s: expected IntegrityFailure, got Ok %A" name r.Id))
